***

### Fixed Code (Secure Code)

This example fixes the vulnerability by using **Prepared Statements** with parameter binding, which separates the SQL command structure from the user-supplied data.

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureExample {

    public static void main(String[] args) {
        String userInput = "admin' OR '1'='1"; // Malicious input

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            // Simulate getting a database connection
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");

            // FIX: Using a PreparedStatement with '?' placeholders.
            // The database driver handles the safe escaping of the input,
            // ensuring the input is treated strictly as data, not executable SQL code.
            String sql = "SELECT * FROM users WHERE username = ? AND password = ?";
            pstmt = conn.prepareStatement(sql);

            // Binding the user input safely to the placeholders.
            pstmt.setString(1, userInput); // Sets the first '?'
            pstmt.setString(2, "somepassword"); // Sets the second '?'

            System.out.println("Executing secure query using prepared statement.");
            rs = pstmt.executeQuery();

            if (rs.next()) {
                System.out.println("Login successful (Secure execution path).");
            } else {
                System.out.println("Login failed.");
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Clean up resources
            try {
                if (rs != null) rs.close();
                if (pstmt != null) pstmt.close();
                if (conn != null) conn.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
